// Define how Sequelize represents one row from the workout_plans table.
// DataTypes describes each column, and the shared Sequelize instance connects
// this model to the configured database.
import { DataTypes } from "sequelize";
import sequelize from "../config/db.js";

// This model describes the existing workout_plans table; it does not create or
// alter it. Attribute names match the existing snake_case column names.
const WorkoutPlan = sequelize.define(
  "WorkoutPlan",
  {
    // Plan identifier generated by the application, not by the database.
    id: {
      type: DataTypes.CHAR(36),
      primaryKey: true,
      allowNull: false,
    },
    // Owner of the plan; deleting the user deletes their plans.
    user_id: {
      type: DataTypes.BIGINT.UNSIGNED,
      allowNull: false,
      references: { model: "users", key: "id" },
      onUpdate: "CASCADE",
      onDelete: "CASCADE",
    },
    // Display name of the plan.
    name: {
      type: DataTypes.STRING(60),
      allowNull: false,
    },
    // Plans start with an empty description unless one is provided.
    description: {
      type: DataTypes.STRING(300),
      allowNull: false,
      defaultValue: "",
    },
    created_at: {
      type: DataTypes.DATE(3),
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
    updated_at: {
      type: DataTypes.DATE(3),
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
  },
  {
    // Explicit mapping avoids Sequelize guessing a table name.
    tableName: "workout_plans",
    // Sequelize manages timestamps using the table's existing column names.
    timestamps: true,
    createdAt: "created_at",
    updatedAt: "updated_at",
    // Match the lookup index and the composite key MariaDB requires.
    indexes: [
      {
        name: "workout_plans_user_updated",
        fields: ["user_id", "updated_at"],
      },
      {
        name: "workout_plans_user_id_unique",
        unique: true,
        fields: ["user_id", "id"],
      },
    ],
  }
);

export default WorkoutPlan;
